using System;using System.Linq;using System.IO;using UnityEngine;using TMPro;using ProjectWait.M.Elevator;public static class InspectWorldUI {public static string Main(){var l=UnityEngine.Object.FindFirstObjectByType<ElevatorLesson>();var d=new{view=l.view.name,parent=l.view.transform.parent?l.view.transform.parent.name:"scene root",isLessonChild=l.view.transform.IsChildOf(l.transform),director=l.scenario.isActiveAndEnabled,texts=l.view.GetComponentsInChildren<TMP_Text>().Select(t=>new{name=t.name,shader=t.fontSharedMaterial.shader.name,mat=t.fontSharedMaterial.name,canvas=t.GetComponentInParent<Canvas>().name,active=t.gameObject.activeInHierarchy}).ToArray(),canvases=l.GetComponentsInChildren<Canvas>(true).Select(c=>c.name).ToArray()};var j=Newtonsoft.Json.JsonConvert.SerializeObject(d,Newtonsoft.Json.Formatting.Indented);File.WriteAllText("Assets/M/CodexTemp/ElevatorCoping_20261030~/WorldUIDiagnostics.json",j);return j;}}